// pipeline.mjs — a esteira: lista de etapas vira um fluxo encadeado.
export function criarPipeline(middlewares) {
  if (!Array.isArray(middlewares)) {
    throw new Error('middlewares precisa ser uma lista');
  }

  return function executar(contexto) {
    let indice = -1;
    const next = () => {
      indice += 1;
      if (indice < middlewares.length) {
        // A etapa atual decide: chama next() (continua) ou não (interrompe).
        return middlewares[indice](contexto, next);
      }
    };
    next();
    return contexto; // o contexto final reflete tudo o que as etapas fizeram
  };
}

// esteira.mjs — a esteira do pedido.
import { criarPipeline } from './pipeline.mjs';

const executar = criarPipeline([
  (ctx, next) => {               // estação 1: autenticação
    ctx.usuario = 'Ana';         // cada estação pode MEXER no contexto...
    next();                      // ...e passar adiante
  },
  (ctx, next) => {               // estação 2: validação
    if (ctx.invalido) {
      ctx.erro = 'pedido inválido'; // não chamou next: encerra aqui
      return;
    }
    next();
  },
  (ctx) => {                     // estação 3: resposta
    ctx.mensagem = `Olá, ${ctx.usuario}! Pedido aprovado.`;
  },
]);

const resultado = executar({});
console.log(resultado.mensagem); // imprime: Olá, Ana! Pedido aprovado.

// Passo 1: a esteira — uma lista de etapas (ctx, next).
const executar = criarPipeline([

  // Passo 2: autenticação — sem token, o fluxo morre aqui.
  (ctx, next) => {
    if (!ctx.token) {
      ctx.status = 401;
      ctx.corpo = 'não autorizado';
      return; // não chamou next: encerra
    }
    ctx.usuario = 'Ana';
    next(); // autorizado: passa adiante
  },

  // Passo 3: validação — pedido vazio também morre aqui.
  (ctx, next) => {
    if (!Array.isArray(ctx.itens) || ctx.itens.length === 0) {
      ctx.status = 400;
      ctx.corpo = 'pedido precisa de itens';
      return; // não chamou next: encerra
    }
    next();
  },

  // Passo 4: resposta — usa o contexto construído pelas etapas anteriores.
  (ctx) => {
    ctx.status = 201;
    ctx.corpo = `pedido de ${ctx.usuario} aprovado com ${ctx.itens.length} item(ns)`;
  },
]);

// Passo 5a: caminho bloqueado — sem token, para na autenticação.
const bloqueado = executar({ itens: [{ nome: 'Café' }] });
console.log(bloqueado.status, bloqueado.corpo); // imprime: 401 não autorizado

// Passo 5b: caminho feliz — token + itens, todas as estações trabalham.
const feliz = executar({ token: 'abc123', itens: [{ nome: 'Café' }] });
console.log(feliz.status, feliz.corpo); // imprime: 201 pedido de Ana aprovado com 1 item(ns)
